def count_moves(z):
    r, c = z // 3, z % 3
    cnt = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if 0 <= r + dr < 3 and 0 <= c + dc < 3:
            cnt += 1
    return cnt
print(count_moves(0), count_moves(1), count_moves(4))

